export function deepEqual(a, b) {
  const assumed = new Map();

  const walk = (x, y) => {
    if (Object.is(x, y)) return true;
    if (x === null || y === null) return false;
    if (typeof x !== 'object' || typeof y !== 'object') return false;

    const seen = assumed.get(x);
    if (seen !== undefined && seen.has(y)) return true;
    if (seen === undefined) assumed.set(x, new Set([y]));
    else seen.add(y);

    const xArray = Array.isArray(x);
    const yArray = Array.isArray(y);
    if (xArray !== yArray) return false;
    if (xArray) {
      if (x.length !== y.length) return false;
      for (let i = 0; i < x.length; i += 1) {
        if (!walk(x[i], y[i])) return false;
      }
      return true;
    }

    const xDate = x instanceof Date;
    const yDate = y instanceof Date;
    if (xDate !== yDate) return false;
    if (xDate) return Object.is(x.getTime(), y.getTime());

    const keys = Object.keys(x);
    if (keys.length !== Object.keys(y).length) return false;
    for (const key of keys) {
      if (!Object.prototype.hasOwnProperty.call(y, key)) return false;
      if (!walk(x[key], y[key])) return false;
    }
    return true;
  };

  return walk(a, b);
}
